export async function handle(db, request) {
  const snapshot = await db.get("count");
  const receipts = await db.get("applied");
  if (receipts.some(row => row.requestId === request.id)) {
    return { applied: true };
  }
  await db.set("count", snapshot + request.delta);
  await db.append("applied", {
    requestId: request.id,
    delta: request.delta
  });
  return { applied: true };
}
